func TestNestedImport(t *testing.T) {
	for i, tc := range []struct {
		input     string
		errorFunc func(err error) bool
	}{
		{
			input: `(t1) {
						respond {args[0]} {args[1]}
					}

					(t2) {
						import t1 {args[0]} 202
					}

					:8080 {
						handle {
							import t2 "foobar"
						}
					}`,
			errorFunc: func(err error) bool {
				return err == nil
			},
		},
		{
			input: `(t1) {
						respond {args[:]}
					}

					(t2) {
						import t1 {args[0]} {args[1]}
					}

					:8080 {
						handle {
							import t2 "foobar" 202
						}
					}`,
